def as_dicts() -> list[dict[str, Any]]:
    from .timeline import point

    out = []
    for i, (pt, kind, title, desc, loc, parts, imp, public) in enumerate(EVENTS):
        out.append({
            "id": f"evt_{i:03d}", "ord": point(pt), "kind": kind, "title": title, "description": desc,
            "location_id": loc, "participants": parts, "importance": imp, "public": public,
        })
    return out
